"""Routes for Terms, generated by Dryv; the engine implements ExploreTermsService."""

from __future__ import annotations

from abc import ABC, abstractmethod
from collections.abc import Awaitable, Callable
from typing import Annotated

from fastapi import APIRouter, Body, Depends, Request

from mzizi_engine.api.schemas.api.explore.models.tag_body import TagBody
from mzizi_engine.api.schemas.api.explore.models.tagged_list import TaggedList
from mzizi_engine.api.schemas.api.explore.models.term_group_list import TermGroupList

__all__ = ["ExploreTermsService", "build_explore_terms_router"]

type Guard = Callable[[Request], Awaitable[None]]
"""An async FastAPI dependency that raises 401 or 403 before the route runs."""


class ExploreTermsService(ABC):
    """What Terms needs from handwritten code. Raise ``fastapi.HTTPException`` for failures."""

    @abstractmethod
    async def list_term_groups(self) -> TermGroupList:
        """Every term group, with its canonical terms."""

    @abstractmethod
    async def tag_texts(self, *, body: TagBody) -> TaggedList:
        """Tag each text with the term groups it mentions."""


def build_explore_terms_router(service: ExploreTermsService, guard: Guard | None = None) -> APIRouter:
    """Routes for Terms, delegating to ``service``; ``guard`` protects every route."""

    router = APIRouter(tags=["Terms"], dependencies=[Depends(guard)] if guard else [])

    @router.get(
        "/v1/explore/terms",
        response_model=TermGroupList,
        status_code=200,
        summary="Every term group, with its canonical terms.",
    )
    async def list_term_groups() -> TermGroupList:
        return await service.list_term_groups()

    @router.post(
        "/v1/explore/terms/tag",
        response_model=TaggedList,
        status_code=200,
        summary="Tag each text with the term groups it mentions.",
    )
    async def tag_texts(
        body: Annotated[TagBody, Body()],
    ) -> TaggedList:
        return await service.tag_texts(body=body)

    return router
